// Classify Support Ticket
const body = $input.first().json.body || $input.first().json;
const inquiry = (body.message || body.ticket_text || '').toLowerCase();

let priority = 'MEDIUM';
let category = 'GENERAL_INQUIRY';

if (inquiry.includes('down') || inquiry.includes('urgent') || inquiry.includes('broken')) {
  priority = 'HIGH';
  category = 'OUTAGE_INCIDENT';
} else if (inquiry.includes('billing') || inquiry.includes('invoice') || inquiry.includes('payment')) {
  priority = 'MEDIUM';
  category = 'BILLING';
}

return [{
  json: {
    ticket_id: body.ticket_id || 'TCK-' + Math.floor(Math.random() * 90000 + 10000),
    category: category,
    priority: priority,
    requires_operator: priority === 'HIGH',
    triage_time: new Date().toISOString()
  }
}];
